def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def validate_dv_scenario(topology, scenario):
    """Validate a distance-vector replay scenario.

    Beyond the shared event rules the scenario must carry an
    ``infinityMetric``: a non-boolean positive integer strictly greater
    than every declared link metric.  Return ``(events, infinity_metric)``.
    """
    if not isinstance(scenario, dict):
        raise InvalidScenario("scenario must be an object")
    infinity_metric = scenario.get("infinityMetric")
    if not _is_int(infinity_metric) or infinity_metric <= 0:
        raise InvalidScenario("infinityMetric must be a positive integer")
    max_link_metric = max(
        (metric for _pair, metric in topology.links), default=0
    )
    if infinity_metric <= max_link_metric:
        raise InvalidScenario(
            "infinityMetric must exceed every link metric"
        )
    return _validate_events(topology, scenario), infinity_metric


def _validate_events(topology, scenario):
    """Validate the shared event sequence; return events in time order.

    Structure, value, reference and time checks live here, alongside a fold
    over :func:`state.apply_event` so illegal event sequences raise
    :class:`InvalidStateTransition` through one authoritative rule set.
    """
    if not isinstance(scenario, dict):
        raise InvalidScenario("scenario must be an object")
    events_raw = scenario.get("events")
    if not isinstance(events_raw, list):
        raise InvalidScenario("events must be an array")

    node_set = topology.node_set
    known_links = topology.link_pairs

    events = []
    state = NetworkState.initial(topology)
    last_time = 0
    for event_raw in events_raw:
        if not isinstance(event_raw, dict):
            raise InvalidScenario("event must be an object")
        time = event_raw.get("time")
        action = event_raw.get("action")
        if not _is_int(time):
            raise InvalidScenario("event time must be an integer")
        if time <= 0 or time <= last_time:
            raise InvalidScenario("event times must strictly increase")
        if not isinstance(action, str):
            raise InvalidScenario("event action must be a string")

        if action in NODE_ACTIONS:
            node = event_raw.get("node")
            if not isinstance(node, str) or node not in node_set:
                raise InvalidScenario("node event must name a declared node")
            event = Event(
                time=time, action=action, raw=dict(event_raw), node=node
            )
        elif action in LINK_ACTIONS:
            source = event_raw.get("from")
            target = event_raw.get("to")
            if not isinstance(source, str) or not isinstance(target, str):
                raise InvalidScenario("link event must name from and to")
            pair = canonical_pair(source, target)
            if pair not in known_links:
                raise InvalidScenario("link event must name a declared link")
            event = Event(
                time=time, action=action, raw=dict(event_raw), pair=pair
            )

def run_replay_dv(topology_path, scenario_path):
    """Distance-vector replay: identical file/error conventions as replay."""
    topology = _read_json(
        topology_path,
        "cannot read topology: {path}",
        "invalid topology",
    )
    if topology is _READ_FAILED:
        return 2
    try:
        topo = validate_topology(topology)
    except InvalidTopology:
        print("invalid topology", file=sys.stderr)
        return 2

    scenario = _read_json(
        scenario_path,
        "cannot read scenario: {path}",
        "invalid scenario",
    )
    if scenario is _READ_FAILED:
        return 2
    try:
        result = replay_dv_validated(topo, scenario)
    except InvalidScenario:
        print("invalid scenario", file=sys.stderr)
        return 2
    _emit(result)
    return 0


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    command = args[0] if args else "help"
    if command == "version":
        print(__version__)
        return 0
    if command == "compute":
        if len(args) != 2:
            print(COMPUTE_USAGE, file=sys.stderr)
            return 2
        return run_compute(args[1])
    if command == "converge":
        if len(args) != 2:
            print(CONVERGE_USAGE, file=sys.stderr)
            return 2
        return run_converge(args[1])
    if command == "replay":
        if len(args) != 3:
            print(REPLAY_USAGE, file=sys.stderr)
            return 2
        return run_replay(args[1], args[2])
    if command == "replay-dv":
        if len(args) != 3:
            print(REPLAY_DV_USAGE, file=sys.stderr)
            return 2
        return run_replay_dv(args[1], args[2])
    if command in {"help", "-h", "--help"}:
        print(USAGE, end="")
        return 0
    print(f"unknown command: {command}", file=sys.stderr)
    print(USAGE, end="", file=sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

def _unreachable_row(ordered_nodes):
    """A fresh row advertising every destination (including self) as down."""
    return {
        destination: {"nextHop": None, "metric": None}
        for destination in ordered_nodes
    }


def distance_vector_failure_round_zero(
    previous, ordered_nodes, active_adjacency, down_nodes
):
    """Round 0 immediately after a failure/recovery event.

    Every online router keeps the routes it advertised in the previous
    converged state, except:

    * a route whose next hop is no longer an available direct neighbor (the
      failed or disconnected neighbor) becomes unreachable;
    * a currently available direct neighbor always advertises the direct
      route again, so a recovered link is usable at once;
    * a down router's whole row is unreachable.

    A recovering router is handed a prior row of its own that is entirely
    unreachable, which leaves it knowing only itself and its currently
    available direct neighbors.
    """
    vectors = {}
    for router in ordered_nodes:
        if router in down_nodes:
            vectors[router] = _unreachable_row(ordered_nodes)
            continue
        table = {}
        prior = previous[router]
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
            elif destination in active_adjacency[router]:
                table[destination] = {
                    "nextHop": destination,
                    "metric": active_adjacency[router][destination],
                }
            else:
                entry = prior[destination]
                hop = entry["nextHop"]
                if hop is None or hop not in active_adjacency[router]:
                    table[destination] = {"nextHop": None, "metric": None}
                else:
                    # A copy, so retained advertisements never alias caller
                    # data or later rounds.
                    table[destination] = dict(entry)
        vectors[router] = table
    return vectors


def distance_vector_round_infinity(
    previous, ordered_nodes, adjacency, down_nodes, infinity_metric
):
    """Synchronously update from prior ads with an infinity threshold.

    Same scan/tie rules as :func:`distance_vector_round`, with no split
    horizon or poison reverse: every available neighbor's previous-round
    advertisement is read.  A candidate metric at or above
    ``infinity_metric`` counts as unreachable.  Down routers keep an
    entirely unreachable row.
    """
    current = {}
    for router in ordered_nodes:
        if router in down_nodes:
            current[router] = _unreachable_row(ordered_nodes)
            continue
        table = {}
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
                continue
            best_metric = None
            best_hop = None
            for neighbor in sorted(adjacency[router]):
                advertised = previous[neighbor][destination]
                if advertised["metric"] is None:
                    continue
                candidate = adjacency[router][neighbor] + advertised["metric"]
                if candidate >= infinity_metric:
                    continue
                # Neighbors are iterated in name order, so the first best
                # candidate keeps the smaller next-hop name on ties.
                if best_metric is None or candidate < best_metric:
                    best_metric = candidate
                    best_hop = neighbor
            if best_metric is None:
                table[destination] = {"nextHop": None, "metric": None}
            else:
                table[destination] = {"nextHop": best_hop, "metric": best_metric}
        current[router] = table
    return current


def distance_vector_failure_convergence(
    round_zero, ordered_nodes, active_adjacency, down_nodes, infinity_metric
):
    """Record round 0 and every later changed round up to a fixed point.

    Metrics strictly increase along the count-to-infinity cycle until they
    reach the threshold and turn unreachable, so the scan terminates with
    every stale route removed.
    """
    rounds = [{"round": 0, "routers": round_zero}]
    vectors = round_zero
    while True:
        updated = distance_vector_round_infinity(
            vectors,
            ordered_nodes,
            active_adjacency,
            down_nodes,
            infinity_metric,
        )
        if updated == vectors:
            break
        vectors = updated
        rounds.append({"round": len(rounds), "routers": vectors})
    return rounds

